// src/components/AdminPanel.js
import React from "react";

function AdminPanel({ candidateForm, setCandidateForm, onSave }) {
  return (
    <div
      style={{
        padding: 20,
        borderRadius: 10,
        backgroundColor: "#e5e5e5",
        boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
        display: "flex",
        flexDirection: "column",
        gap: 12,
      }}
    >
      <h3 style={{ marginBottom: 12 }}>Add / Edit Candidate</h3>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          onSave();
        }}
        style={{ display: "flex", flexDirection: "column", gap: 10 }}
      >
        <input
          type="text"
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, firstName: e.target.value })
          }
          style={{
            padding: 8,
            borderRadius: 6,
            border: "1px solid #94a3b8",
            width: "100%",
          }}
          required
        />

        <input
          type="text"
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, lastName: e.target.value })
          }
          style={{
            padding: 8,
            borderRadius: 6,
            border: "1px solid #94a3b8",
            width: "100%",
          }}
          required
        />

        <input
          type="text"
          placeholder="Candidacy Position"
          value={candidateForm.candidacy}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, candidacy: e.target.value })
          }
          style={{
            padding: 8,
            borderRadius: 6,
            border: "1px solid #94a3b8",
            width: "100%",
          }}
          required
        />

        <textarea
          placeholder="Description"
          value={candidateForm.description || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, description: e.target.value })
          }
          style={{
            padding: 8,
            borderRadius: 6,
            border: "1px solid #94a3b8",
            width: "100%",
            minHeight: 80,
          }}
        />

        <input
          type="file"
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, image: e.target.files[0] })
          }
          style={{ marginTop: 4 }}
        />

        <button
          type="submit"
          style={{
            marginTop: 10,
            padding: "8px 12px",
            borderRadius: 6,
            border: "none",
            backgroundColor: "#1e40af",
            color: "white",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Save Candidate
        </button>
      </form>
    </div>
  );
}

export default AdminPanel;
